/* Слова-подсказки для классификации группы, если слово не попало в словарь. */
const CATEGORY_HINTS = [
  [/ов|ев|ый|ий|ая|ой|ист|ник|щик|тель|арь|ер|ор|ант|ент|олог|граф|ец$/, 'people'],
];

/** Приводит слово к «базовой» форме для подписи. */
const BASE_FORM = {
  новичок: 'новичков', новички: 'новичков', новичка: 'новичков', новичков: 'новичков',
  игрок: 'игроков', игроки: 'игроков', игрока: 'игроков', игроков: 'игроков',
  опытный: 'опытных игроков', опытных: 'опытных игроков',
};

/** Нормализует слово: нижний регистр, ё → е. */
export function normWord(w) {
  return String(w || '').toLowerCase().replace(/ё/g, 'е');
}

/**
 * Находит все упоминания категорий в тексте:
 * [{ category, word, index, end }]
 */
export function findMentions(text) {
  const s = normWord(text);
  const out = [];
  for (const cat of CATEGORIES) {
    // Граница начала слова обязательна: иначе «фея» найдётся внутри «картофеля»,
    // «осы» — внутри «вопросы», «кот» — внутри «который».
    const re = new RegExp(`(?:^|[^а-яё])(${cat.src})`, 'g');
    let m;
    while ((m = re.exec(s)) !== null) {
      const word = m[1];
      const index = m.index + m[0].length - word.length;
      out.push({ category: cat.id, word, index, end: index + word.length });
      re.lastIndex = index + 1;
    }
  }
  // убираем дубли (одно слово попало в две категории) — оставляем более специфичную
  out.sort((a, b) => a.index - b.index || b.end - b.index - (a.end - a.index));
  const cleaned = [];
  for (const m of out) {
    const overlap = cleaned.find((c) => m.index < c.end && m.end > c.index);
    if (overlap) continue;
    cleaned.push(m);
  }
  return cleaned;
}

/** Группирует упоминания в «именованные группы»: новички, опытные игроки, … */
export function findNamedGroups(text) {
  const s = normWord(text);
  const groups = [];
  const push = (name, category, index, end) => {
    const key = name.toLowerCase();
    const found = groups.find((g) => g.key === key);
    if (found) { found.count++; found.last = Math.max(found.last, end); return; }
    groups.push({ key, name, category, first: index, last: end, count: 1 });
  };
  // Люди/животные: «80 новичков», «15 опытных игроков», «25 мальчиков»
  for (const cat of CATEGORIES) {
    const re = new RegExp(`(?:^|[^а-яё])((?:[а-яё]+\\s+){0,2})(${cat.src})`, 'g');
    let m;
    while ((m = re.exec(s)) !== null) {
      const prefix = (m[1] || '').trim();
      const word = m[2];
      // «опытные игроки» — берём прилагательное перед существительным
      const adj = prefix.split(/\s+/).filter(Boolean).pop() || '';
      // «больше/меньше/много» — не прилагательные, а сравнения: «в 2 раза больше взрослых»
      const isAdj = /^(опытн|нов|юн|старш|младш|взросл|маленьк|больш|бывал|лучш|худш|молод|пожил)/.test(adj)
        && !/^(больше|больше|меньше|много|мало)/.test(adj);
      const name = isAdj ? `${adj} ${word}` : word;
      push(name, cat.id, m.index, m.index + m[0].length);
    }
  }
  // Техника: «поезда», «машины» — без прилагательных
  return groups;
}

/** Сколько человек/предметов в группе по подписи (для «людей»). */
export function categoryLabel(category) {
  return CATEGORIES.find((c) => c.id === category)?.label || 'штук';
}

/** Подбирает подпись для категории: «человек», «животных», «машин». */
export function categoryCounter(category) {
  switch (category) {
    case 'people': return 'человек';
    case 'animals': return 'животных';
    case 'vehicles': return 'машин';
    case 'groups': return 'групп';
    case 'goods': return '';
    default: return '';
  }
}

/**
 * Ищет группы, которые упоминаются в условии, и их начальные значения.
 * Используется как «страховка»: даже если шаблон не сработал, мы знаем,
 * о каких группах идёт речь и можем посчитать их по дням.
 */
export function bootstrapGroups(text) {
  const groups = findNamedGroups(text);
  return groups.map((g) => ({ ...g }));
}

export { BASE_FORM };
